examples.template:
Scaffold(
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 3),
    containerColor = MonarchTheme.colors.bgCanvas,
    snackbarHost = { MonarchSnackbarHost(hostState = snackbars) },
) { padding ->
    Column(modifier = Modifier.padding(padding), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
        notes.forEach { note ->
            Row(verticalAlignment = Alignment.CenterVertically) {
                MonarchText(text = note, modifier = Modifier.weight(1f))
                MonarchIconButton(label = "Delete $note", onClick = { delete(note) }) {
                    MonarchIcon(SampleIcons.Trash, contentDescription = null)
                }
            }
        }
    }
}

examples.setupTemplate:
val snackbars = remember { SnackbarHostState() }
val scope = rememberCoroutineScope()
var notes by remember { mutableStateOf(listOf({{notes.0}}, {{notes.1}}, {{notes.2}})) }
val delete: (String) -> Unit = { note ->
    val index = notes.indexOf(note)
    notes = notes - note
    scope.launch {
        val result = snackbars.showSnackbar(
            message = {{toast.title}} + "\n" + note,
            actionLabel = {{toast.action}},
            duration = SnackbarDuration.Long,
        )
        when (result) {
            SnackbarResult.ActionPerformed -> {
                notes = notes.toMutableList().apply { add(index.coerceAtMost(size), note) }
                snackbars.showSnackbar(message = "Restored")
            }
            SnackbarResult.Dismissed -> Unit // Delete on the server here.
        }
    }
}
// The first note has just been deleted: the toast offers Undo until it goes away.
LaunchedEffect(Unit) { delete({{notes.0}}) }

